StructuredBuffer<uint> clusters : register(t1, space0);
StructuredBuffer<Probe> probes : register(t2, space0);
StructuredBuffer<Decal> decals : register(t3, space0);
StructuredBuffer<uint> decal_atlas : register(t4, space0);
